+    this.vel[i * 3 + 2] = (Math.random() - 0.5) * spread;
+    this.life[i] = life;
+    this.maxLife[i] = life;
+    this.baseSize[i] = size;
+    this.sizes[i] = size;
+    this.alphas[i] = 0.5;
+    this.dirty = true;
+  }
+
+  update(dt) {
+    for (let i = 0; i < this.count; i++) {
+      if (this.life[i] <= 0) continue;
+      this.life[i] -= dt;
+      if (this.life[i] <= 0) {
+        this.alphas[i] = 0;
+        this.positions[i * 3 + 1] = -999;
+        this.dirty = true;
+        continue;
+      }
+      const k = this.life[i] / this.maxLife[i];
+      this.positions[i * 3] += this.vel[i * 3] * dt;
+      this.positions[i * 3 + 1] += this.vel[i * 3 + 1] * dt;
+      this.positions[i * 3 + 2] += this.vel[i * 3 + 2] * dt;
+      this.vel[i * 3] *= 0.985;
+      this.vel[i * 3 + 2] *= 0.985;
+      this.vel[i * 3 + 1] += dt * 0.2;
+      this.sizes[i] = this.baseSize[i] * (1.6 - k * 0.6);
+      this.alphas[i] = k * 0.42;
+      this.dirty = true;
+    }
+    if (this.dirty) {
+      this.geo.attributes.position.needsUpdate = true;
+      this.geo.attributes.aColor.needsUpdate = true;
+      this.geo.attributes.aSize.needsUpdate = true;
+      this.geo.attributes.aAlpha.needsUpdate = true;
+      this.dirty = false;
+    }
+  }
+
+  reset() {
+    for (let i = 0; i < this.count; i++) {
+      this.life[i] = 0;
+      this.alphas[i] = 0;
+      this.positions[i * 3 + 1] = -999;
+    }
+    this.geo.attributes.position.needsUpdate = true;
+    this.geo.attributes.aAlpha.needsUpdate = true;
+    this.cursor = 0;
+  }
+
+  dispose() {
+    this.geo.dispose();
+    this.material.dispose();
+    this.points.parent?.remove(this.points);
+  }
+}
+
+/* ═══════════════════════════════════════════════════════════════════
+   Race setup
+   ═══════════════════════════════════════════════════════════════════ */
+const GRID_GAP = 9.5;
+const GRID_FIRST = 9;
+const TOTAL_LAPS = 3;
+
+function hideAllScreens() {
+  for (const el of [dom.menu, dom.draw, dom.build]) el.classList.remove('is-active');
+}
+
+function gridPose(slot, lateral) {
+  const behind = GRID_FIRST + slot * GRID_GAP;
+  const s = sampleAtDistance(race.track, -behind);
+  return {
+    x: s.x + s.nx * lateral,
+    z: s.z + s.nz * lateral,
+    yaw: Math.atan2(s.tx, s.tz),
+    s
+  };
+}
+
+function enterRace(trackData) {
+  if (race) {
+    race.smoke?.dispose();
+    race.world?.dispose();
+    race.playerCar?.dispose();
+    race.ai?.forEach((a) => a.model.dispose());
+    race = null;
+  }
+
+  const world = createRaceWorld(trackData);
+  const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 7000);
+  const playerCar = createCar({
+    paint: 0xc90d19, accent: 0xf3efe5, accent2: 0xff4d1f, driver: 0xf3efe5, number: '07', player: true
+  });
+  world.scene.add(playerCar.root);
+
+  const ai = AI_TEAMS.map((team, i) => {
+    const model = createCar({
+      paint: team.paint, accent: team.accent, accent2: team.accent2, driver: team.driver,
+      number: ['21', '03', '88'][i], showDecals: true
+    });
+    world.scene.add(model.root);
+    return {
+      name: team.name,
+      color: `#${team.paint.toString(16).padStart(6, '0')}`,
+      model,
+      dist: 0,
+      speed: 0,
+      finished: false,
+      finishTime: null,
+      phase: Math.random() * TAU,
+      lateral: i % 2 === 0 ? 2.9 : -2.9
+    };
+  });
+
+  const smoke = new SmokeSystem(world.scene);
+
+  race = {
+    track: trackData,
+    world,
+    camera,
+    playerCar,
+    ai,
+    smoke,
+    locator: new TrackLocator(trackData, 18),
+    map: null,
+    state: 'countdown',
+    time: 0,
+    countdownT: 0,
+    countdownStep: -1,
+    resultsTimer: 0,
+    resultsShown: false,
+    cameraReady: false,
+    cameraMode: 0,
+    camLook: new THREE.Vector3(),
+    leaderTimer: 0,
+    player: {
+      pos: { x: 0, z: 0 }, vel: { x: 0, z: 0 }, yaw: 0, steer: 0, throttle: 0, brake: 0,
+      vLong: 0, vLat: 0, prevVLong: 0, yawRate: 0, offroad: false, offTimer: 0,
+      lapsCompleted: 0, lapStart: 0, prevS: 0, sNorm: 0, sectors: [false, false, false],
+      bestLap: null, lastLap: null, topSpeed: 0, finished: false, finishTime: null,
+      finishPosition: 4, drs: false, trackDist: 0
+    }
+  };
+
+  race.map = buildMinimapBase(trackData);
+  dom.minimapTrackName.textContent = trackData.name;
+  resetRaceState();
+
+  appState = 'race';
+  hideAllScreens();
+  showModal(dom.pause, false);
+  showModal(dom.results, false);
+  showRaceHud(true);
+  dom.webgl.classList.remove('is-hidden', 'is-dim');
+  dom.minimap.width = 520;
+  dom.minimap.height = 220;
+  dom.minimapTrackName.textContent = trackData.name;
+}
+
+function setCarPose(model, x, z, yaw) {
+  model.root.position.set(x, 0, z);
+  model.root.rotation.y = yaw;
+}
+
+function resetRaceState() {
+  const r = race;
+  const p = r.player;
+
+  // player starts P4, last on the grid
+  const pose = gridPose(3, -2.9);
+  p.pos = { x: pose.x, z: pose.z };
+  p.vel = { x: 0, z: 0 };
+  p.yaw = pose.yaw;
+  p.steer = 0; p.throttle = 0; p.brake = 0;
+  p.vLong = 0; p.vLat = 0; p.prevVLong = 0; p.yawRate = 0;
+  p.offroad = false; p.offTimer = 0;
+  p.lapsCompleted = 0; p.lapStart = 0;
+  p.sectors = [false, false, false];
+  p.bestLap = readBest(r.track.seed);
+  p.lastLap = null; p.topSpeed = 0;
+  p.finished = false; p.finishTime = null; p.finishPosition = 4;
+  p.drs = false; p.trackDist = 0;
+  p.sNorm = ((r.locator.nearest(pose.x, pose.z).index % r.track.N) / r.track.N);
+  p.prevS = p.sNorm;
+  setCarPose(r.playerCar, pose.x, pose.z, pose.yaw);
+  r.playerCar.body.rotation.set(0, 0, 0);
+  r.playerCar.setDRS(false);
+  r.playerCar.setBrake(false);
+
+  r.ai.forEach((a, i) => {
+    const gp = gridPose(i, i % 2 === 0 ? 2.9 : -2.9);
+    a.dist = -(GRID_FIRST + i * GRID_GAP);
+    a.speed = 0;
+    a.finished = false;
+    a.finishTime = null;
+    a.lateral = i % 2 === 0 ? 2.9 : -2.9;
+    a.phase = Math.random() * TAU;
+    setCarPose(a.model, gp.x, gp.z, gp.yaw);
+    a.model.body.rotation.set(0, 0, 0);
+    a.model.setDRS(false);
+  });
+
+  r.time = 0;
+  r.countdownT = 0;
+  r.countdownStep = -1;
+  r.countdownElapsed = 0;
+  r.resultsTimer = 0;
+  r.resultsShown = false;
+  r.cameraReady = false;
+  r.cameraMode = 0;
+  r.leaderTimer = 0;
+  r.state = 'countdown';
+  r.world.setStartLights(0);
+  r.smoke.reset();
+
+  dom.countdown.classList.add('show');
+  dom.countdownValue.textContent = '3';
+  dom.countdownValue.classList.remove('go');
+  dom.raceMessage.classList.remove('show');
+  dom.offTrack.classList.remove('show');
+  dom.controlsHint.classList.remove('is-faded');
+  dom.hudTime.textContent = '0:00.000';
+  dom.hudLast.textContent = '—:—.———';
+  dom.hudBest.textContent = p.bestLap ? formatTime(p.bestLap) : '—:—.———';
+  dom.hudPosition.textContent = '4';
+  dom.hudPositionTotal.textContent = '/4';
+  dom.hudLap.innerHTML = 'LAP 1<em>/3</em>';
+  dom.hudSpeed.textContent = '0';
+  dom.hudGear.textContent = 'N';
+  dom.speedoFill.setAttribute('stroke-dashoffset', '100');
+  dom.throttleFill.style.height = '0%';
+  dom.hudDrs.classList.remove('is-active');
+  showModal(dom.results, false);
+  showModal(dom.pause, false);
+  audio.startRace();
+  audio.setPaused(false);
+  audio.countdown(3);
+}
+
+function disposeRace() {
+  if (!race) return;
+  audio.stopRace();
+  race.smoke?.dispose();
+  race.world?.dispose();
+  race.playerCar?.dispose();
+  race.ai?.forEach((a) => a.model.dispose());
+  race = null;
+}
+
+/* ═══════════════════════════════════════════════════════════════════
+   Minimap
+   ═══════════════════════════════════════════════════════════════════ */
+function buildMinimapBase(track) {
+  const c = document.createElement('canvas');
+  c.width = 520; c.height = 220;
+  const ctx = c.getContext('2d');
+  const pad = 24;
+  const scale = Math.min(
+    (c.width - pad * 2) / Math.max(track.bbox.width, 1),
+    (c.height - pad * 2) / Math.max(track.bbox.depth, 1)
+  );
+  const ox = c.width / 2 - track.centerX * scale;
+  const oy = c.height / 2 - track.centerZ * scale;
+  const map = (x, z) => ({ x: x * scale + ox, y: z * scale + oy });
+
+  ctx.clearRect(0, 0, c.width, c.height);
+  const bg = ctx.createRadialGradient(c.width / 2, c.height / 2, 0, c.width / 2, c.height / 2, c.width * 0.6);
+  bg.addColorStop(0, 'rgba(255,255,255,.025)');
+  bg.addColorStop(1, 'rgba(0,0,0,.18)');
+  ctx.fillStyle = bg;
+  ctx.fillRect(0, 0, c.width, c.height);
+
+  const path = new Path2D();
+  track.samples.forEach((s, i) => {
+    const q = map(s.x, s.z);
+    if (i === 0) path.moveTo(q.x, q.y); else path.lineTo(q.x, q.y);
+  });
+  path.closePath();
+
+  ctx.save();
+  ctx.lineJoin = 'round';
+  ctx.lineCap = 'round';
+  ctx.strokeStyle = 'rgba(255,77,31,.15)';
+  ctx.lineWidth = 14;
+  ctx.shadowColor = 'rgba(255,77,31,.8)';
+  ctx.shadowBlur = 12;
+  ctx.stroke(path);
+  ctx.shadowBlur = 0;
+  ctx.strokeStyle = 'rgba(6,8,11,.9)';
+  ctx.lineWidth = 8;
+  ctx.stroke(path);
+  ctx.strokeStyle = '#f3efe5';
+  ctx.lineWidth = 3;
+  ctx.stroke(path);
+
+  // sector dots
+  for (const frac of [0.25, 0.5, 0.75]) {
+    const s = track.samples[Math.floor(track.N * frac)];
+    const q = map(s.x, s.z);
+    ctx.fillStyle = 'rgba(255,77,31,.9)';
+    ctx.beginPath();
+    ctx.arc(q.x, q.y, 2.2, 0, TAU);
+    ctx.fill();
+  }
+
+  // start line
+  const st = track.samples[0];
+  const a = map(st.x, st.z);
+  const normal = { x: st.nx, y: st.nz };
+  ctx.strokeStyle = '#fff';
+  ctx.lineWidth = 2;
+  ctx.beginPath();
+  ctx.moveTo(a.x - normal.x * 6, a.y - normal.y * 6);
+  ctx.lineTo(a.x + normal.x * 6, a.y + normal.y * 6);
+  ctx.stroke();
+  ctx.restore();
+
+  return { canvas: c, scale, ox, oy };
+}
+
+function mapPoint(x, z) {
+  return { x: x * race.map.scale + race.map.ox, y: z * race.map.scale + race.map.oy };
+}
+
+function drawMinimap() {
+  if (!race || !race.map) return;
+  const ctx = dom.minimap.getContext('2d');
+  ctx.clearRect(0, 0, dom.minimap.width, dom.minimap.height);
+  ctx.drawImage(race.map.canvas, 0, 0);
+
+  for (const a of race.ai) {
+    const s = sampleAtDistance(race.track, a.dist);
+    const lat = a.lateral + Math.sin(a.dist / 48 + a.phase) * 0.7;
+    const q = mapPoint(s.x + s.nx * lat, s.z + s.nz * lat);
+    ctx.save();
+    ctx.fillStyle = a.color;
+    ctx.strokeStyle = 'rgba(4,6,9,.9)';
+    ctx.lineWidth = 2;
+    ctx.beginPath();
+    ctx.arc(q.x, q.y, 4.2, 0, TAU);
+    ctx.fill();
+    ctx.stroke();
+    ctx.restore();
+  }
+
+  const p = race.player;
+  const q = mapPoint(p.pos.x, p.pos.z);
+  const dirX = Math.sin(p.yaw), dirZ = Math.cos(p.yaw);
+  const perpX = dirZ, perpZ = -dirX;
+  ctx.save();
+  ctx.shadowColor = 'rgba(255,77,31,.9)';
+  ctx.shadowBlur = 10;
+  ctx.fillStyle = '#ff4d1f';
+  ctx.strokeStyle = '#07090c';
+  ctx.lineWidth = 2;
+  ctx.beginPath();
+  ctx.moveTo(q.x + dirX * 9, q.y + dirZ * 9);
+  ctx.lineTo(q.x - dirX * 5 + perpX * 5.5, q.y - dirZ * 5 + perpZ * 5.5);
+  ctx.lineTo(q.x - dirX * 2, q.y - dirZ * 2);
+  ctx.lineTo(q.x - dirX * 5 - perpX * 5.5, q.y - dirZ * 5 - perpZ * 5.5);
+  ctx.closePath();
+  ctx.fill();
+  ctx.stroke();
+  ctx.restore();
+}
+
+/* ═══════════════════════════════════════════════════════════════════
+   Standings / progress
+   ═══════════════════════════════════════════════════════════════════ */
+function playerProgress() {
+  const p = race.player;
+  if (p.finished) return TOTAL_LAPS;
+  const s = p.sNorm;
+  return p.lapsCompleted + (p.lapsCompleted === 0 && s > 0.72 ? s - 1 : s);
+}
+
+function getStandings() {
+  const p = race.player;
+  const playerP = playerProgress();
+  const rows = [{
+    name: 'YOU', color: '#ff4d1f', progress: playerP,
+    isPlayer: true, lap: Math.min(TOTAL_LAPS, p.lapsCompleted + 1), finished: p.finished
+  }];
+  for (const a of race.ai) {
+    const prog = a.dist / race.track.length;
+    rows.push({
+      name: a.name, color: a.color, progress: prog,
+      isPlayer: false, lap: clamp(Math.floor(a.dist / race.track.length) + 1, 1, TOTAL_LAPS),
+      finished: a.finished
+    });
+  }
+  rows.sort((a, b) => b.progress - a.progress);
+  return rows;
+}
+
+/* ═══════════════════════════════════════════════════════════════════
+   Placeholder physics section
+   ═══════════════════════════════════════════════════════════════════ */

content.text:
Now part 2B: physics, AI, HUD, camera, race update, results, pause.

Need import `formatShortTime` used in menu. yes.

`wrapAngle` not imported; avoid.

Implement `updatePlayerPhysics`, `updateAI`, `updateProgress`, `updateHUD`, `updateRaceCamera`, `updateRace`, `finishRace`, `showResults`, `pause`, `resume`, `goToDraw`.

Let's write.

Physics note p.sNorm set after. Need p.offroad computed before physics using last frame. At reset, locate. Use `p.offroad` state.

Progress:
```
function updatePlayerProgress(dt) {
 const p=race.player; if (p.finished) return;
 const s=p.sNorm;
 const forward = p.vel.x*Math.cos? tangent sample: race.track.samples[idx]
 ...
 if (moving forward) {
   if (s<0.9) { if(s>0.12) sectors[0]=true; ...}
 }
 crossing = p.prevS>0.82 && s<0.18 && forwardDot>0.8
 if (crossing) {
   if (sectors[0]&&[1]&&[2]) completeLap();
   else sectors=[false,false,false];
 }
 p.prevS=s;
}
```
Wait setting sectors at start: s=0.985 >0.9 no. After crossing s=.01; no. Then they pass .12 → sector0 true, etc. At end of lap, s=.98, sectors all true. Crossing valid. Good.
But if a player's grid position is s=0.984 and they move backward/forward, prevS. fine.
Sector thresholds 0.15,0.4,0.65. Use `s>0.15`, etc. all while s<0.9.

`completeLap`:
```
const p=race.player;
const lapTime=race.time - p.lapStart;
if (race.time>0 && lapTime>5000) { p.lastLap=lapTime; if(!p.bestLap||lapTime<p.bestLap){p.bestLap=lapTime;writeBest(...);} }
p.lapsCompleted++;
p.lapStart=race.time;
p.sectors=[false,false,false];
if (p.lapsCompleted>=TOTAL_LAPS) finishRace();
else { showRaceMessage(`LAP ${p.lapsCompleted+1} / ${TOTAL_LAPS}`, p.lapsCompleted===2?'FINAL LAP':'...'); }
```
Lap display after crossing lap1: p.lapsCompleted=1 → lap 2. Good. Message "LAP 2 / 3" or FINAL LAP.
For last lap crossing finish; show finish.
Potential quick first crossing: sectors false → no complete, reset sectors. prevS update after. Good.

`updatePlayerPhysics` must set `p.yawRate`. Determine DRS from last sample curvature (`race.track.samples[locator.lastIndex].k`) but update after movement. Use p.lastK store. Start 0. Compute after near.

```
const drs = race.state==='racing' && p.vLong>55 && Math.abs(p.lastK||0) < 1/400 && p.throttle>0.4;
```
This would be true almost everywhere on straights, fine. Drawn tracks have straights. set.

Input reading active state only racing. During finished, no input. During countdown, car static; we can still run physics with 0; but skip. Simpler update only when racing/finished/paused? Paused no updates at all. For countdown we don't call physics; we update car pose? already. Set idle visuals in updateRace (wheel no spin). Good.

`updatePlayerPhysics` called for racing and finished. For finished active false, no gas/brake and p.throttle damp to 0, speed coasts. Good.

After movement:
```
const near = locator.nearest(...)
const sample = track.samples[near.index];
p.sNorm = near.index/track.N; p.trackDist=near.dist; p.lastK = sample.k;
p.offroad = near.dist > halfWidth+1.0;
p.onKerb = ...
if (p.offroad) offTimer += dt; else offTimer=Math.max(0, offTimer-dt*2);
if (p.offroad && near.dist>halfWidth+28) offTimer+=dt;
if (offTimer>2.8 && race.state==='racing') recoverPlayer();
```
But on grass near dist maybe 7-20, offTimer grows and reset after 2.8s. Good.

`recoverPlayer` uses sample pose and resets velocity maybe 0. Show toast "RECOVERED". Add `audio.tone`. Also reset sectors? Should reset sectors to avoid cheating. Yes set sectors=[false,false,false]? That would cost the lap; harsh but fair. Hmm, if they just went off track they should still be able to complete lap, but recovery cuts distance slightly. Resetting sectors would prevent lap completion that lap (they'd have to pass sectors again after recovery, they will as they continue). If they recover before the missing sector, they'd re-hit thresholds later. But if they recovered after all sectors, resetting means no lap; unfair. Don't reset sectors. Position jump may cause crossing weird; set prevS to recovered s.

Visual car updates:
```
function updatePlayerVisual(dt) {
 const p=race.player, car=race.playerCar;
 car.root.position...
 car.root.rotation.y = p.yaw;
 const longAccel=(p.vLong-p.prevVLong)/Math.max(dt,1e-3);
 p.prevVLong = p.vLong;
 const targetPitch=clamp(-longAccel*0.003,-.06,.06);
 car.body.rotation.x = damp(...,7,dt);
 car.body.rotation.z = damp(..., clamp(p.vLong*p.yawRate*0.0035,-.07,.07),7,dt);
 const steer = p.steer * lerp(0.5,0.16, clamp(Math.abs(p.vLong)/55,0,1));
 for (const w of car.wheels) { w.spin.rotation.x += (p.vLong / w.radius)*dt; if (w.front) w.steer.rotation.y = damp(w.steer.rotation.y, steer, 16, dt); }
 car.setBrake(p.brake>0.08);
 car.setDRS(p.drs);
 // particles
}
```
Note p.prevVLong update in physics maybe; do here.

Particle emission:
```
race.emitAccum += dt* (offroad? 50 : slip>2.5? 26 :0)
while accumulator>1 { emit at rear wheels positions; }
```
Need world-space rear wheel pos:
```
const fx=sin yaw, fz=cos yaw; rear = pos - f*1.5; left/right = r*±0.85; y 0.25
color = offroad ? {tan} : {gray}
```
Use THREE.Color constants stored in race (`dustColor`, `smokeColor`). Add to race object? Create in enterRace after race assignment or lazily. Use static Colors created at module top:
```
const DUST_COLOR = new THREE.Color(0xc9b48d); const SMOKE_COLOR = new THREE.Color(0xd9d9d9);
```
Define before.
For finished no emission unless sliding.
Also emission at high lateral slip. p.vLat can be >.

`updateAI(dt)`:
For each ai, simulate only if state racing or finished? During finished, AI also continue. In countdown they don't move. Use race.state==='racing' or 'finished'.
```
const L=track.length;
const normalized = ((a.dist % L)+L)%L;
const idx = Math.floor(normalized/track.step)%N;
let target = track.speedProfile[idx] * DIFFICULTY[diffLevel].factor;
if (a.finished) target *= .55;
if (a.speed < target) a.speed = Math.min(target, a.speed + a.accel*dt);
else a.speed = Math.max(target, a.speed - 26*dt);
a.dist += a.speed*dt;
if (!a.finished && a.dist >= TOTAL_LAPS*L) { a.finished=true; a.finishTime=race.time; }
const s=sampleAtDistance(track,a.dist);
lateral = a.lateral + sin(a.dist/45+a.phase)*0.9;
x = s.x + s.nx*lateral ...
yaw just tangent. Could add slip look? 
body roll = clamp(-s.k*a.speed*a.speed*0.002, -.05,.05)? sign.
wheels spin.
steer rotation = clamp(-s.k*8,-.4,.4)? front wheels in corner; use s.k * speed? Actually steering target ~ angle; just use `s.k * 3` clamped .35, sign maybe. Visual.
```
AI speed profile indexing near negative distance: normalize fine.
AI start acceleration: `a.accel=DIFFICULTY.accel`. Use stored? add when entering race `a.accel = ...` not necessary, access DIFFICULTY[diffLevel]. Set in reset? We'll read each frame but diffLevel fixed.
- Also rubber band? If player far ahead AI could speed up? Not necessary.
- If difficulty changed between races (draw screen), reset uses current diffLevel.

AI finished but target 0.55 speed means they slow down after finish; their distance increases, standing progress keeps. Fine.

`updateHUD`:
- position computed from standings each frame maybe. Use getStandings every frame (4 items, cheap).
