461: class SmokeSystem {
462:   constructor(scene) {
463:     this.count = 260;
464:     this.cursor = 0;
465:     this.positions = new Float32Array(this.count * 3);
466:     this.colors = new Float32Array(this.count * 3);
467:     this.sizes = new Float32Array(this.count);
468:     this.alphas = new Float32Array(this.count);
469:     this.life = new Float32Array(this.count);
470:     this.maxLife = new Float32Array(this.count);
471:     this.vel = new Float32Array(this.count * 3);
472:     this.baseSize = new Float32Array(this.count);
473:     for (let i = 0; i < this.count; i++) {
474:       this.positions[i * 3 + 1] = -999;
475:       this.alphas[i] = 0;
476:     }
477:     const geo = new THREE.BufferGeometry();
478:     geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
479:     geo.setAttribute('aColor', new THREE.BufferAttribute(this.colors, 3));
480:     geo.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1));
481:     geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1));
482:     this.geo = geo;
483:     this.material = new THREE.ShaderMaterial({
484:       transparent: true,
485:       depthWrite: false,
486:       vertexShader: `
487:         attribute float aSize;
488:         attribute float aAlpha;
489:         attribute vec3 aColor;
490:         varying float vAlpha;
491:         varying vec3 vColor;
492:         void main() {
493:           vAlpha = aAlpha;
494:           vColor = aColor;
495:           vec4 mv = modelViewMatrix * vec4(position, 1.0);
496:           gl_PointSize = aSize * (340.0 / max(1.0, -mv.z));
497:           gl_Position = projectionMatrix * mv;
498:         }
499:       `,
500:       fragmentShader: `
501:         varying float vAlpha;
502:         varying vec3 vColor;
503:         void main() {
504:           float d = length(gl_PointCoord - vec2(0.5));
505:           if (d > 0.5) discard;
506:           gl_FragColor = vec4(vColor, vAlpha * smoothstep(0.5, 0.08, d));
507:         }
508:       `
509:     });
510:     this.points = new THREE.Points(geo, this.material);
511:     this.points.frustumCulled = false;
512:     scene.add(this.points);
513:     this.dirty = false;
514:   }
515: 
516:   emit(x, y, z, color, size = 0.55, life = 1.1, spread = 1.4) {
517:     const i = this.cursor;
518:     this.cursor = (this.cursor + 1) % this.count;
519:     this.positions[i * 3] = x + (Math.random() - 0.5) * 0.5;
520:     this.positions[i * 3 + 1] = y + Math.random() * 0.2;
521:     this.positions[i * 3 + 2] = z + (Math.random() - 0.5) * 0.5;
522:     this.colors[i * 3] = color.r;
523:     this.colors[i * 3 + 1] = color.g;
524:     this.colors[i * 3 + 2] = color.b;
525:     this.vel[i * 3] = (Math.random() - 0.5) * spread;
526:     this.vel[i * 3 + 1] = 0.4 + Math.random() * spread;
527:     this.vel[i * 3 + 2] = (Math.random() - 0.5) * spread;
528:     this.life[i] = life;
529:     this.maxLife[i] = life;
530:     this.baseSize[i] = size;
531:     this.sizes[i] = size;
532:     this.alphas[i] = 0.5;
533:     this.dirty = true;
534:   }
535: 
536:   update(dt) {
537:     for (let i = 0; i < this.count; i++) {
538:       if (this.life[i] <= 0) continue;
539:       this.life[i] -= dt;
540:       if (this.life[i] <= 0) {
541:         this.alphas[i] = 0;
542:         this.positions[i * 3 + 1] = -999;
543:         this.dirty = true;
544:         continue;
545:       }
546:       const k = this.life[i] / this.maxLife[i];
547:       this.positions[i * 3] += this.vel[i * 3] * dt;
548:       this.positions[i * 3 + 1] += this.vel[i * 3 + 1] * dt;
549:       this.positions[i * 3 + 2] += this.vel[i * 3 + 2] * dt;
550:       this.vel[i * 3] *= 0.985;
551:       this.vel[i * 3 + 2] *= 0.985;
552:       this.vel[i * 3 + 1] += dt * 0.2;
553:       this.sizes[i] = this.baseSize[i] * (1.6 - k * 0.6);
554:       this.alphas[i] = k * 0.42;
555:       this.dirty = true;
556:     }
557:     if (this.dirty) {
558:       this.geo.attributes.position.needsUpdate = true;
559:       this.geo.attributes.aColor.needsUpdate = true;
560:       this.geo.attributes.aSize.needsUpdate = true;
561:       this.geo.attributes.aAlpha.needsUpdate = true;
562:       this.dirty = false;
563:     }
564:   }
565: 
566:   reset() {
567:     for (let i = 0; i < this.count; i++) {
568:       this.life[i] = 0;
569:       this.alphas[i] = 0;
570:       this.positions[i * 3 + 1] = -999;
571:     }
572:     this.geo.attributes.position.needsUpdate = true;
573:     this.geo.attributes.aAlpha.needsUpdate = true;
574:     this.cursor = 0;
575:   }
576: 
577:   dispose() {
578:     this.geo.dispose();
579:     this.material.dispose();
580:     this.points.parent?.remove(this.points);
581:   }
582: }
