779: function buildMinimapBase(track) {
780:   const c = document.createElement('canvas');
781:   c.width = 520; c.height = 220;
782:   const ctx = c.getContext('2d');
783:   const pad = 24;
784:   const scale = Math.min(
785:     (c.width - pad * 2) / Math.max(track.bbox.width, 1),
786:     (c.height - pad * 2) / Math.max(track.bbox.depth, 1)
787:   );
788:   const ox = c.width / 2 - track.centerX * scale;
789:   const oy = c.height / 2 - track.centerZ * scale;
790:   const map = (x, z) => ({ x: x * scale + ox, y: z * scale + oy });
791: 
792:   ctx.clearRect(0, 0, c.width, c.height);
793:   const bg = ctx.createRadialGradient(c.width / 2, c.height / 2, 0, c.width / 2, c.height / 2, c.width * 0.6);
794:   bg.addColorStop(0, 'rgba(255,255,255,.025)');
795:   bg.addColorStop(1, 'rgba(0,0,0,.18)');
796:   ctx.fillStyle = bg;
797:   ctx.fillRect(0, 0, c.width, c.height);
798: 
799:   const path = new Path2D();
800:   track.samples.forEach((s, i) => {
801:     const q = map(s.x, s.z);
802:     if (i === 0) path.moveTo(q.x, q.y); else path.lineTo(q.x, q.y);
803:   });
804:   path.closePath();
805: 
806:   ctx.save();
807:   ctx.lineJoin = 'round';
808:   ctx.lineCap = 'round';
809:   ctx.strokeStyle = 'rgba(255,77,31,.15)';
810:   ctx.lineWidth = 14;
811:   ctx.shadowColor = 'rgba(255,77,31,.8)';
812:   ctx.shadowBlur = 12;
813:   ctx.stroke(path);
814:   ctx.shadowBlur = 0;
815:   ctx.strokeStyle = 'rgba(6,8,11,.9)';
816:   ctx.lineWidth = 8;
817:   ctx.stroke(path);
818:   ctx.strokeStyle = '#f3efe5';
819:   ctx.lineWidth = 3;
820:   ctx.stroke(path);
821: 
822:   // sector dots
823:   for (const frac of [0.25, 0.5, 0.75]) {
824:     const s = track.samples[Math.floor(track.N * frac)];
825:     const q = map(s.x, s.z);
826:     ctx.fillStyle = 'rgba(255,77,31,.9)';
827:     ctx.beginPath();
828:     ctx.arc(q.x, q.y, 2.2, 0, TAU);
829:     ctx.fill();
830:   }
831: 
832:   // start line
833:   const st = track.samples[0];
834:   const a = map(st.x, st.z);
835:   const normal = { x: st.nx, y: st.nz };
836:   ctx.strokeStyle = '#fff';
837:   ctx.lineWidth = 2;
838:   ctx.beginPath();
839:   ctx.moveTo(a.x - normal.x * 6, a.y - normal.y * 6);
840:   ctx.lineTo(a.x + normal.x * 6, a.y + normal.y * 6);
841:   ctx.stroke();
842:   ctx.restore();
843: 
844:   return { canvas: c, scale, ox, oy };
845: }
