885:   ctx.lineTo(q.x - dirX * 2, q.y - dirZ * 2);
886:   ctx.lineTo(q.x - dirX * 5 - perpX * 5.5, q.y - dirZ * 5 - perpZ * 5.5);
887:   ctx.closePath();
888:   ctx.fill();
